import React, { useState, useEffect } from 'react'
import './styles/GroupCard.scss'
import axios from 'axios';
import DataCard from './DataCard';

const GroupCard = () => {
    const [tables, setTables] = useState({})

    useEffect(() => {
        const fetchData = async () => {
            try {
                const { data } = await axios.get('http://localhost:8800/groups')
                setTables(data)
            } catch (error) {
                console.error('Failed to fetch data', error)
            }
        }

        fetchData()
    }, [])
    return (
        <div className='group-card-container'>
            {Object.keys(tables).map(tableName => (
                <div className='section' key={tableName}>
                    <h2>{tableName.charAt(0).toUpperCase() + tableName.slice(1)}</h2>
                    {tables[tableName].length > 0 ? (
                        tables[tableName].map((item, index) => (
                            <CataCard key={index} data={item} />
                        ))
                    ) : (
                        <p>No data found in {tableName}.</p>
                    )}
                </div>
            ))}
        </div>
    )
}

export default GroupCard
